"""HTTP API endpoints."""
from __future__ import annotations

import shutil

from fastapi import APIRouter, HTTPException, UploadFile
from fastapi.responses import Response

from ..config import settings
from ..ingest.loader import load_input
from ..ingest.validate import ValidationError, validate_upload
from ..jobs.store import store
from ..models.schemas import JobStatus, UploadResponse
from ..pipeline.compare import run_comparison
from ..viz.render import render_bbox_overlay, render_original, render_side_by_side

router = APIRouter(prefix="/api")


@router.post("/upload", response_model=UploadResponse)
async def upload(file_a: UploadFile, file_b: UploadFile) -> UploadResponse:
    saved = []
    for tag, f in (("a", file_a), ("b", file_b)):
        data = await f.read()
        try:
            ext = validate_upload(f.filename or f"file_{tag}", data)
        except ValidationError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        saved.append((tag, data, ext))

    job = store.create(file_a=settings.upload_dir / "pending_a", file_b=settings.upload_dir / "pending_b")
    job_dir = settings.upload_dir / job.job_id
    job_dir.mkdir(parents=True, exist_ok=True)
    for tag, data, ext in saved:
        path = job_dir / f"{tag}{ext}"
        path.write_bytes(data)
        if tag == "a":
            job.file_a = path
        else:
            job.file_b = path
    return UploadResponse(job_id=job.job_id, file_a=job.file_a.name, file_b=job.file_b.name)


@router.post("/compare/{job_id}", response_model=JobStatus)
def compare(job_id: str) -> JobStatus:
    job = store.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Unknown job id")
    job.status = "processing"
    try:
        result = run_comparison(job.job_id, job.file_a, job.file_b)
        job.diff = result.diff
        job.stats = result.stats
        job.summary = result.summary
        job.status = "done"
    except Exception as exc:  # surface pipeline failures to the client
        job.status = "failed"
        job.error = str(exc)
    return _job_status(job_id)


@router.get("/jobs/{job_id}", response_model=JobStatus)
def job_status(job_id: str) -> JobStatus:
    return _job_status(job_id)


def _job_status(job_id: str) -> JobStatus:
    job = store.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Unknown job id")
    return JobStatus(
        job_id=job.job_id,
        status=job.status,  # type: ignore[arg-type]
        error=job.error,
        diff_result=job.diff,
        stats=job.stats,
        summary=job.summary,
    )


@router.get("/jobs/{job_id}/summary")
def get_summary(job_id: str) -> dict:
    job = _require_done(job_id)
    return {"summary": job.summary}


@router.get("/jobs/{job_id}/stats")
def get_stats(job_id: str):
    return _require_done(job_id).stats


@router.get("/jobs/{job_id}/visualization")
def visualization(job_id: str, mode: str = "bbox") -> Response:
    job = _require_done(job_id)
    doc_a = load_input(job.file_a)
    doc_b = load_input(job.file_b)
    try:
        if mode == "bbox":
            png = render_bbox_overlay(doc_b.page, job.diff)
        elif mode == "side_by_side":
            png = render_side_by_side(doc_a.page, doc_b.page, job.diff)
        elif mode == "original_a":
            png = render_original(doc_a.page)
        elif mode == "original_b":
            png = render_original(doc_b.page)
        else:
            raise HTTPException(
                status_code=400,
                detail="mode must be one of: bbox, side_by_side, original_a, original_b",
            )
    finally:
        doc_a.close()
        doc_b.close()
    return Response(content=png, media_type="image/png")


@router.delete("/jobs/{job_id}")
def delete_job(job_id: str) -> dict:
    job = store.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Unknown job id")
    shutil.rmtree(settings.upload_dir / job_id, ignore_errors=True)
    store.delete(job_id)
    return {"deleted": job_id}


def _require_done(job_id: str):
    job = store.get(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Unknown job id")
    if job.status != "done":
        raise HTTPException(status_code=409, detail=f"Job status is '{job.status}', not 'done'")
    return job

"""Upload validation: extension, size, and magic-byte checks (FR-1)."""
from __future__ import annotations

from pathlib import Path

from ..config import settings

# magic bytes for the formats we accept
_MAGIC = {
    ".pdf": [b"%PDF"],
    ".png": [b"\x89PNG"],
    ".jpg": [b"\xff\xd8\xff"],
    ".jpeg": [b"\xff\xd8\xff"],
}


class ValidationError(ValueError):
    pass


def validate_upload(filename: str, data: bytes) -> str:
    """Validate an uploaded file. Returns the normalized extension.

    Raises ValidationError with a user-facing message on failure.
    """
    ext = Path(filename).suffix.lower()
    if ext not in settings.allowed_extensions:
        raise ValidationError(
            f"Unsupported file type '{ext}'. Allowed: {', '.join(settings.allowed_extensions)}"
        )
    if not data:
        raise ValidationError(f"File '{filename}' is empty.")
    if len(data) > settings.max_file_size_mb * 1024 * 1024:
        raise ValidationError(
            f"File '{filename}' exceeds the {settings.max_file_size_mb} MB size limit."
        )
    if not any(data.startswith(m) for m in _MAGIC[ext]):
        raise ValidationError(
            f"File '{filename}' does not look like a valid {ext} file (bad file header)."
        )
    return ext

"""Rule-based natural-language change summary (FR-6).

Pure string templating over computed stats — no LLM anywhere. Mirrors the
example paragraph style from the requirements document.
"""
from __future__ import annotations

from ..config import settings
from ..models.diff_result import DiffResult
from ..models.schemas import RegionStat, StatsSummary
from .severity import bucket_severity

_NUM_WORDS = {
    1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
    6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
}


def _num_word(n: int) -> str:
    return _NUM_WORDS.get(n, str(n))


def _describe(stat: RegionStat) -> str:
    what = "annotation" if stat.kind == "text" else "drawing element"
    loc = stat.location if stat.location == "center" else f"{stat.location} region"
    if stat.change_type == "added":
        return f"a new {what} has appeared in the {loc}"
    if stat.change_type == "removed":
        return f"an existing {what} in the {loc} has been removed"
    if stat.change_type == "moved":
        return f"a {what} near the {loc} has shifted position"
    # modified
    if stat.detail and stat.kind == "text":
        return f"an annotation in the {loc} was changed ({stat.detail})"
    return f"structural modifications were detected near the {loc}"


def generate_summary(diff: DiffResult, stats: StatsSummary) -> str:
    if stats.total_regions == 0:
        base = "No significant differences were detected between the two drawings."
        if diff.compare_mode == "approx-geometry+text":
            base += (
                " Note: at least one input is a raster scan, so geometry was "
                "compared approximately from traced drawing lines and text via OCR."
            )
        return base

    severity = bucket_severity(stats.total_changed_area_fraction)
    n = stats.total_regions
    parts = [
        f"The comparison identified {_num_word(n)} "
        f"{severity} change{'s' if n != 1 else ''} between the two drawings."
    ]

    top = stats.per_region[: settings.max_summary_regions]
    if top:
        sentences = [_describe(s) for s in top]
        if len(sentences) == 1:
            body = sentences[0].capitalize() + "."
        else:
            body = (
                sentences[0].capitalize()
                + ", while "
                + "; additionally, ".join(sentences[1:])
                + "."
            )
        parts.append(body)

    remaining = n - len(top)
    if remaining > 0:
        parts.append(
            f"{_num_word(remaining).capitalize()} further smaller "
            f"change{'s were' if remaining != 1 else ' was'} also detected."
        )

    parts.append(
        "These changes affect approximately "
        f"{stats.total_changed_area_fraction * 100:.1f}% of the total drawing area."
    )

    if diff.compare_mode == "approx-geometry+text":
        parts.append(
            "Note: at least one input is a raster scan, so geometry changes "
            "were detected approximately by tracing drawing lines on both "
            "pages, and text was compared via OCR; small changes may be "
            "missed and positions are approximate."
        )

    parts += [n for n in diff.notes if n.startswith("Warning:")]

    return " ".join(parts)

"""Map a normalized centroid to a human location label via a 3x3 grid."""
from __future__ import annotations


def bucket_location(cx: float, cy: float) -> str:
    col = "left" if cx < 1 / 3 else ("right" if cx > 2 / 3 else "center")
    row = "upper" if cy < 1 / 3 else ("lower" if cy > 2 / 3 else "middle")

    if row == "middle" and col == "center":
        return "center"
    if row == "middle":
        return col  # "left" / "right" (middle band)
    if col == "center":
        return row  # "upper" / "lower" (middle column)
    return f"{row}-{col}"  # e.g. "lower-right"

"""Bucket total changed-area fraction into a severity word."""
from __future__ import annotations

from ..config import settings


def bucket_severity(area_fraction: float) -> str:
    if area_fraction < settings.severity_minor:
        return "minor"
    if area_fraction < settings.severity_moderate:
        return "moderate"
    return "significant"

"""Extract vector primitives and text spans from a native-vector PDF page.

Coordinates are normalized to [0,1] against the page rect immediately so
every later stage is resolution/page-size independent.
"""
from __future__ import annotations

from dataclasses import dataclass, field

import fitz

Point = tuple[float, float]


@dataclass
class Primitive:
    kind: str  # "l" line, "c" bezier curve, "re" rect, "qu" quad
    points: list[Point]  # normalized endpoints/control points
    width: float = 0.0

    @property
    def endpoints(self) -> list[Point]:
        """Points used for connectivity clustering (first and last)."""
        if not self.points:
            return []
        return [self.points[0], self.points[-1]]


@dataclass
class RawTextSpan:
    text: str
    bbox: tuple[float, float, float, float]  # normalized
    size: float = 0.0
    confidence: float = 1.0


def _norm_point(p, w: float, h: float) -> Point:
    return (p.x / w, p.y / h)


def _norm_rect(r: fitz.Rect, w: float, h: float) -> tuple[float, float, float, float]:
    return (r.x0 / w, r.y0 / h, r.x1 / w, r.y1 / h)


def extract_primitives(page: fitz.Page) -> list[Primitive]:
    w, h = page.rect.width, page.rect.height
    primitives: list[Primitive] = []
    for drawing in page.get_drawings():
        width = drawing.get("width") or 0.0
        for item in drawing["items"]:
            op = item[0]
            if op == "l":  # line: (op, p1, p2)
                pts = [_norm_point(item[1], w, h), _norm_point(item[2], w, h)]
            elif op == "c":  # bezier: (op, p1, p2, p3, p4)
                pts = [_norm_point(p, w, h) for p in item[1:5]]
            elif op == "re":  # rect: (op, rect, orientation?)
                r = item[1]
                pts = [
                    (r.x0 / w, r.y0 / h),
                    (r.x1 / w, r.y0 / h),
                    (r.x1 / w, r.y1 / h),
                    (r.x0 / w, r.y1 / h),
                ]
            elif op == "qu":  # quad: (op, quad)
                q = item[1]
                pts = [_norm_point(p, w, h) for p in (q.ul, q.ur, q.lr, q.ll)]
            else:
                continue
            primitives.append(Primitive(kind=op, points=pts, width=width))
    return primitives


def extract_text_spans(page: fitz.Page) -> list[RawTextSpan]:
    w, h = page.rect.width, page.rect.height
    spans: list[RawTextSpan] = []
    data = page.get_text("dict")
    for block in data.get("blocks", []):
        for line in block.get("lines", []):
            for span in line.get("spans", []):
                text = span["text"].strip()
                if not text:
                    continue
                spans.append(
                    RawTextSpan(
                        text=text,
                        bbox=_norm_rect(fitz.Rect(span["bbox"]), w, h),
                        size=span.get("size", 0.0),
                    )
                )
    return spans

"""Visualization rendering (FR-4).

Pages are rasterized here purely for human display — the diff itself was
already decided on structured entities before any pixel exists. Boxes are
drawn with Pillow on the rendered page.
"""
from __future__ import annotations

import io

import fitz
from PIL import Image, ImageDraw, ImageFont

from ..config import settings
from ..models.diff_result import ChangeType, DiffResult, Region

_COLORS = {
    ChangeType.ADDED: (46, 160, 67),      # green
    ChangeType.REMOVED: (218, 54, 51),    # red
    ChangeType.MOVED: (227, 179, 65),     # amber
    ChangeType.MODIFIED: (31, 111, 235),  # blue
}


def render_page(page: fitz.Page, dpi: int | None = None) -> Image.Image:
    pix = page.get_pixmap(dpi=dpi or settings.render_dpi)
    return Image.frombytes("RGB", (pix.width, pix.height), pix.samples)


def _draw_regions(img: Image.Image, regions: list[Region], use_old_bbox: bool) -> Image.Image:
    draw = ImageDraw.Draw(img)
    w, h = img.size
    try:
        font = ImageFont.truetype("arial.ttf", max(12, h // 90))
    except OSError:
        font = ImageFont.load_default()

    for region in regions:
        bbox = region.old_bbox if (use_old_bbox and region.old_bbox) else region.bbox
        if use_old_bbox and region.change_type == ChangeType.ADDED:
            continue  # additions don't exist on the old page
        if not use_old_bbox and region.change_type == ChangeType.REMOVED:
            bbox = region.bbox  # removals drawn where the element used to be
        color = _COLORS[region.change_type]
        px = [bbox[0] * w, bbox[1] * h, bbox[2] * w, bbox[3] * h]
        # pad tiny boxes so they stay visible
        pad = max(2.0, 0.002 * max(w, h))
        px = [px[0] - pad, px[1] - pad, px[2] + pad, px[3] + pad]
        draw.rectangle(px, outline=color, width=max(2, h // 400))
        tag = region.change_type.value
        draw.text((px[0], max(0, px[1] - font.size - 2)), tag, fill=color, font=font)
    return img


def render_bbox_overlay(page_b: fitz.Page, diff: DiffResult) -> bytes:
    """New version annotated with all change regions."""
    img = _draw_regions(render_page(page_b), diff.regions, use_old_bbox=False)
    return _to_png(img)


def render_side_by_side(page_a: fitz.Page, page_b: fitz.Page, diff: DiffResult) -> bytes:
    img_a = _draw_regions(render_page(page_a), diff.regions, use_old_bbox=True)
    img_b = _draw_regions(render_page(page_b), diff.regions, use_old_bbox=False)
    # equalize heights
    target_h = max(img_a.height, img_b.height)
    def _scale(im: Image.Image) -> Image.Image:
        if im.height == target_h:
            return im
        w = round(im.width * target_h / im.height)
        return im.resize((w, target_h))
    img_a, img_b = _scale(img_a), _scale(img_b)
    gap = 16
    combo = Image.new("RGB", (img_a.width + gap + img_b.width, target_h), (255, 255, 255))
    combo.paste(img_a, (0, 0))
    combo.paste(img_b, (img_a.width + gap, 0))
    return _to_png(combo)


def render_original(page: fitz.Page) -> bytes:
    return _to_png(render_page(page))


def _to_png(img: Image.Image) -> bytes:
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return buf.getvalue()

const API = "/api";

const state = { fileA: null, fileB: null, jobId: null };

function bindDropzone(zoneId, inputId, key) {
  const zone = document.getElementById(zoneId);
  const input = document.getElementById(inputId);
  zone.addEventListener("click", () => input.click());
  input.addEventListener("change", () => setFile(zone, input.files[0], key));
  zone.addEventListener("dragover", (e) => e.preventDefault());
  zone.addEventListener("drop", (e) => {
    e.preventDefault();
    if (e.dataTransfer.files.length) setFile(zone, e.dataTransfer.files[0], key);
  });
}

function setFile(zone, file, key) {
  if (!file) return;
  state[key] = file;
  zone.classList.add("hasfile");
  zone.innerHTML = `<b>${file.name}</b><br><small>${(file.size / 1024 / 1024).toFixed(1)} MB</small>`;
  document.getElementById("compare-btn").disabled = !(state.fileA && state.fileB);
}

bindDropzone("drop-a", "file-a", "fileA");
bindDropzone("drop-b", "file-b", "fileB");

const statusEl = document.getElementById("status");

document.getElementById("compare-btn").addEventListener("click", async () => {
  const btn = document.getElementById("compare-btn");
  btn.disabled = true;
  statusEl.textContent = "Uploading…";
  try {
    const form = new FormData();
    form.append("file_a", state.fileA);
    form.append("file_b", state.fileB);
    const up = await fetch(`${API}/upload`, { method: "POST", body: form });
    if (!up.ok) throw new Error((await up.json()).detail || "upload failed");
    const { job_id } = await up.json();
    state.jobId = job_id;

    statusEl.textContent = "Comparing… (extracting entities and matching)";
    const cmp = await fetch(`${API}/compare/${job_id}`, { method: "POST" });
    if (!cmp.ok) throw new Error((await cmp.json()).detail || "compare failed");
    const job = await cmp.json();
    if (job.status === "failed") throw new Error(job.error || "comparison failed");

    statusEl.textContent = "Done.";
    renderResults(job);
  } catch (err) {
    statusEl.textContent = `Error: ${err.message}`;
  } finally {
    btn.disabled = false;
  }
});

function renderResults(job) {
  for (const id of ["viz-card", "stats-card", "summary-card"])
    document.getElementById(id).classList.remove("hidden");

  setVizMode("bbox");

  const s = job.stats;
  document.getElementById("stat-tiles").innerHTML = `
    <div class="stat"><b>${s.total_regions}</b><span>total changes</span></div>
    <div class="stat"><b>${s.added_count}</b><span>added</span></div>
    <div class="stat"><b>${s.removed_count}</b><span>removed</span></div>
    <div class="stat"><b>${s.moved_count}</b><span>moved</span></div>
    <div class="stat"><b>${s.modified_count}</b><span>modified</span></div>
    <div class="stat"><b>${(s.total_changed_area_fraction * 100).toFixed(1)}%</b><span>area changed</span></div>`;

  document.getElementById("region-rows").innerHTML = s.per_region
    .slice(0, 100)
    .map(
      (r) => `<tr>
        <td><span class="chip ${r.change_type}">${r.change_type}</span></td>
        <td>${r.kind}</td>
        <td>${r.location}</td>
        <td>${(r.area_fraction * 100).toFixed(2)}%</td>
        <td>${r.detail || r.label || ""}</td>
      </tr>`
    )
    .join("");

  document.getElementById("summary-text").textContent = job.summary;
  document.getElementById("notes").innerHTML = (job.diff_result.notes || [])
    .map((n) => `<div class="note">⚠ ${n}</div>`)
    .join("");
}

document.getElementById("viz-tabs").addEventListener("click", (e) => {
  const btn = e.target.closest("button[data-mode]");
  if (btn) setVizMode(btn.dataset.mode);
});

function setVizMode(mode) {
  document
    .querySelectorAll("#viz-tabs button")
    .forEach((b) => b.classList.toggle("active", b.dataset.mode === mode));
  document.getElementById("viz-img").src =
    `${API}/jobs/${state.jobId}/visualization?mode=${mode}&t=${Date.now()}`;
}
